"""1522 (#11 enemy_body_size_variants, knocked down): Record-MissionCoverage-v1518.ps1 with two knockdown refinements
(1518a: Corvo blasted the overseer from in front, so he saw Corvo; the re-stand used his position mid-slide and he was up
again before the press):
- -BlastFromBehind: Corvo (host) stands 3 m behind the walking target, facing his back, so he stays unaware.
- -KnockdownSettle: after the blast the target is sampled every loop; once he has moved more than 1 m and then stays
  within 0.15 m between two samples, the source is stood 1 m from him on the caster's side, looks down (-PressPitch)
  and presses at once. The choke rule takes a target that IsOnGround (ragdoll or get-up pose; choke.rulehandler,
  confirmed static), which lasts until he is standing again.
Generated by make_mission_coverage_v1522.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-MissionCoverage-v1518.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("[switch]$HoldTarget,[double]$PressPitch=-999)", "[switch]$HoldTarget,[double]$PressPitch=-999,[switch]$BlastFromBehind,[switch]$KnockdownSettle)")
first = s.index('\n') + 1
s = s[:first] + "# 1522 (#11): -BlastFromBehind, -KnockdownSettle. Generated by make_mission_coverage_v1522.py.\n" + s[first:]
rep("      $wx=[double]$np[0]+3*$fx;$wy=[double]$np[1]+3*$fy;C host (P $wx $wy ($sz+1.7) ([Math]::Atan2(-$fy,-$fx)*180/[Math]::PI))",
    "      $bs=if($BlastFromBehind){-3}else{3};$wx=[double]$np[0]+$bs*$fx;$wy=[double]$np[1]+$bs*$fy;C host (P $wx $wy ($sz+1.7) ([Math]::Atan2(-$bs*$fy,-$bs*$fx)*180/[Math]::PI))")
# Settle tracking replaces the timed knockdown re-stand and press.
rep("      if($KnockdownApproach-and!$replaced-and$t-ge(450+$delay)){",
    "      if($KnockdownSettle-and$row.blastedAt-and!$acted){$tq=@(Living $source|Where-Object {$_.spawnerName-eq$TargetSpawner-and$_.unique})\n"
    "       if($tq.Count){$qp=$tq[0].position;$moved=[Math]::Sqrt([Math]::Pow([double]$qp[0]-[double]$np[0],2)+[Math]::Pow([double]$qp[1]-[double]$np[1],2))\n"
    "        $step=if($row.lastKnock){[Math]::Sqrt([Math]::Pow([double]$qp[0]-[double]$row.lastKnock[0],2)+[Math]::Pow([double]$qp[1]-[double]$row.lastKnock[1],2))}else{99};$row.lastKnock=$qp\n"
    "        if($moved-gt1.0-and$step-lt.15-and!$row.settledAt){$row.settledAt=$t;$replaced=$true;$kx=[double]$qp[0]-[double]$row.windblastFrom[0];$ky=[double]$qp[1]-[double]$row.windblastFrom[1];$kl=[Math]::Max(.1,[Math]::Sqrt($kx*$kx+$ky*$ky));$kx/=$kl;$ky/=$kl\n"
    "         C $source (P ([double]$qp[0]-1.0*$kx) ([double]$qp[1]-1.0*$ky) ([double]$qp[2]+1.7) ([Math]::Atan2($ky,$kx)*180/[Math]::PI));$row.knockedAt=$qp;$row.knockFlight=[Math]::Round($moved,2)\n"
    "         if($PressPitch-gt-90){try{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch $PressPitch -Quick|Out-Null}catch{}}\n"
    "         $acted=Start-Process (Get-Process -Id $PID).Path -ArgumentList (@('-NoProfile','-File',\"$lab/Send-D2Input.ps1\",'-Role',$source)+$(if($TakedownKind-eq'choke'){@('-Button','RightShoulder','-DurationMs','6500')}else{@('-RightTrigger','255','-DurationMs','200')})) -WindowStyle Hidden -PassThru;$row.actedAt=$watch.ElapsedMilliseconds}}}\n"
    "      if($KnockdownApproach-and!$KnockdownSettle-and!$replaced-and$t-ge(450+$delay)){")
# Without a settle the regular press would fire at 700+delay; with -KnockdownSettle it waits (up to 4 s after the blast).
rep("      if(!$acted-and$t-ge(700+$delay)){", "      if(!$acted-and$t-ge(700+$delay)-and(!$KnockdownSettle-or$t-ge4400)){")
rep("      if(!$replaced-and$t-ge(450+$delay)-and!$Perch){", "      if(!$replaced-and$t-ge(450+$delay)-and!$Perch-and!$KnockdownSettle){")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-MissionCoverage-v1522.ps1').write_bytes(out.encode('utf-8'))
print('ok')
